import base64
import json

SECRET = b"top-secret-signing-key"


def _b64url_decode(segment):
    pad = "=" * (-len(segment) % 4)
    return base64.urlsafe_b64decode(segment + pad)


def verify(token):
    """Return the token's payload dict if valid, else None.

    BUG: this decodes the payload WITHOUT verifying the HMAC signature and
    without checking the algorithm, so anyone can forge a token (including an
    alg:none token with no signature) and have it accepted.
    """
    try:
        header_b64, payload_b64, sig_b64 = token.split(".")
    except ValueError:
        return None
    return json.loads(_b64url_decode(payload_b64))

