import base64
import hashlib
import hmac
import json

import auth


def _b64(raw):
    return base64.urlsafe_b64encode(raw).rstrip(b"=").decode()


def make_token(payload, alg="HS256", secret=None):
    secret = auth.SECRET if secret is None else secret
    header = {"alg": alg, "typ": "JWT"}
    signing = _b64(json.dumps(header, separators=(",", ":")).encode()) + "." + _b64(
        json.dumps(payload, separators=(",", ":")).encode())
    sig = _b64(hmac.new(secret, signing.encode(), hashlib.sha256).digest())
    return signing + "." + sig


def test_accepts_valid_token():
    assert auth.verify(make_token({"user": "ada"})) == {"user": "ada"}


def test_rejects_tampered_payload():
    token = make_token({"user": "ada", "admin": False})
    header_b64, _payload_b64, sig_b64 = token.split(".")
    forged = _b64(json.dumps({"user": "ada", "admin": True}, separators=(",", ":")).encode())
    assert auth.verify(header_b64 + "." + forged + "." + sig_b64) is None


def test_rejects_alg_none():
    header = {"alg": "none", "typ": "JWT"}
    signing = _b64(json.dumps(header, separators=(",", ":")).encode()) + "." + _b64(
        json.dumps({"user": "admin"}, separators=(",", ":")).encode())
    assert auth.verify(signing + ".") is None


def test_rejects_wrong_secret():
    assert auth.verify(make_token({"user": "ada"}, secret=b"attacker-key")) is None

