import base64
import hashlib
import hmac
import json

SECRET = b"top-secret-signing-key"


def _b64url_decode(segment):
    pad = "=" * (-len(segment) % 4)
    return base64.urlsafe_b64decode(segment + pad)


def verify(token):
    """Return the token's payload dict if the HS256 signature is valid, else None."""
    try:
        header_b64, payload_b64, sig_b64 = token.split(".")
    except ValueError:
        return None
    try:
        header = json.loads(_b64url_decode(header_b64))
    except Exception:
        return None
    if header.get("alg") != "HS256":
        return None
    signing = (header_b64 + "." + payload_b64).encode()
    expected = hmac.new(SECRET, signing, hashlib.sha256).digest()
    try:
        actual = _b64url_decode(sig_b64)
    except Exception:
        return None
    if not hmac.compare_digest(expected, actual):
        return None
    try:
        return json.loads(_b64url_decode(payload_b64))
    except Exception:
        return None

